38	            if (lastName.equals(canonical(existing.getLastName()))
39	                    && address.equals(OwnerAddresses.normalize(existing.getAddress()))) {
40	                matches.add(existing);
41	            }
42	        }
43	
44	        if (matches.isEmpty()) {
45	            householdIdOut.set(null); // unique household — nothing to share
46	            return;
47	        }
48	
49	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
50	            throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
51	        }
52	
53	        // Caller opted into sharing: give this owner and every match the same stable identifier.
54	        String householdId = deriveHouseholdId(lastName, address);
55	        for (Owner match : matches) {
56	            if (match.getHouseholdId() == null) {
57	                match.setHouseholdId(householdId);
58	                ownerRepository.save(match);
59	            }
60	        }
61	        householdIdOut.set(new HouseholdId(householdId));
62	    }
63	
64	    /** Deterministic, stable identifier for a household — same lastName + address always yields it. */
65	    private static String deriveHouseholdId(String canonicalLastName, String canonicalAddress) {
66	        String seed = "household:" + canonicalLastName + "|" + canonicalAddress;
67	        return UUID.nameUUIDFromBytes(seed.getBytes(StandardCharsets.UTF_8)).toString();
68	    }
69	
70	    /** Trim, collapse internal whitespace runs to a single space and lower-case for comparison. */
71	    private static String canonical(String value) {
72	        if (value == null) {
73	            return "";
74	        }
75	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
76	    }
77	}
