7	/**
8	 * Runs in the create-owner pipeline after {@link BuildOwner} and before {@link SaveOwner}. Counts
9	 * the existing owners that already share this owner's firstName and lastName (compared
10	 * case-insensitively) at the moment before it is stored, and stamps that count onto the built owner
11	 * in place so later steps store and respond with it. As it runs before the owner is saved, the
12	 * count excludes the owner being created; the first owner of a name gets 0.
13	 */
14	public class AssignNamesakeCount {
15	
16	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
17	        String firstName = owner.getFirstName();
18	        String lastName = owner.getLastName();
19	        int count = 0;
20	        for (Owner existing : ownerRepository.findAll()) {
21	            if (equalsIgnoreCase(firstName, existing.getFirstName())
22	                    && equalsIgnoreCase(lastName, existing.getLastName())) {
23	                count++;
24	            }
25	        }
26	        owner.setNamesakeCount(count);
27	    }
28	
29	    private static boolean equalsIgnoreCase(String a, String b) {
30	        return a == null ? b == null : a.equalsIgnoreCase(b);
31	    }
32	}
